package main
import("encoding/json";"os";"reflect";"strings";d "discovery.local/author")
func schema(t reflect.Type)map[string]any{if t.Kind()==reflect.Pointer{return schema(t.Elem())};switch t.Kind(){case reflect.String:return map[string]any{"type":"string"};case reflect.Bool:return map[string]any{"type":"boolean"};case reflect.Int,reflect.Int64:return map[string]any{"type":"integer"};case reflect.Slice:return map[string]any{"type":"array","items":schema(t.Elem())};case reflect.Struct:p:=map[string]any{};r:=[]string{};for i:=0;i<t.NumField();i++{f:=t.Field(i);tag:=strings.Split(f.Tag.Get("json"),",");if tag[0]=="-"{continue};p[tag[0]]=schema(f.Type);if len(tag)==1{r=append(r,tag[0])}};return map[string]any{"type":"object","properties":p,"required":r,"additionalProperties":false}};panic(t.String())}
func main(){result:=map[string]any{};for name,value:=range map[string]any{"request":d.Request{},"state":d.State{},"result":d.Result{},"capture":d.Capture{},"source":d.Source{}}{result[name]=schema(reflect.TypeOf(value))};if e:=json.NewEncoder(os.Stdout).Encode(result);e!=nil{panic(e)}}
